    "id": "grammar.read-grammar-selection-included-range-part",
    "source": "rust/src/translation/grammar_selection_included_range_rules/part_1.rs",
    "name": "read_grammar_selection_included_range_part",
    "inventoryName": "read grammar selection included range part",
    "sourceText": "pub fn read_grammar_selection_included_range_part(\n    plan: &[f64],\n    row: f64,\n    position: f64,\n    output: f64,\n    width: f64,\n) -> Vec<f64> {\n    if ((((((plan.len() as f64) < 12f64) || (((plan.len() as f64) % 4f64) != 0f64))\n        || !(self::ml_math::is_integer(row)))\n        || (row < 0f64))\n        || ((row % 4f64) != 0f64))\n        || (row > (plan.len() as f64))\n    {\n        Vec::<f64>::new()\n    } else if row == (plan.len() as f64) {\n        vec![1f64]\n    } else {\n        {\n            let start = (self::ml_array::optional_at(plan, self::ml_array::number_index(row)))\n                .unwrap_or(-1f64);\n            {\n                let end =\n                    (self::ml_array::optional_at(plan, self::ml_array::number_index(row + 1f64)))\n                        .unwrap_or(-1f64);\n                {\n                    let output_start = (self::ml_array::optional_at(\n                        plan,\n                        self::ml_array::number_index(row + 2f64),\n                    ))\n                    .unwrap_or(-1f64);\n                    {\n                        let output_end = (self::ml_array::optional_at(\n                            plan,\n                            self::ml_array::number_index(row + 3f64),\n                        ))\n                        .unwrap_or(-1f64);\n                        {\n                            let following = row + 4f64;\n                            {\n                                let following_position = (self::ml_array::optional_at(\n                                    plan,\n                                    self::ml_array::number_index(following),\n                                ))\n                                .unwrap_or(end);\n                                if output_start == output_end {\n                                    if (position != start) || (output != output_start) {\n                                        Vec::<f64>::new()\n                                    } else {\n                                        vec![\n                                            0f64,\n                                            following,\n                                            following_position,\n                                            output,\n                                            start,\n                                            end,\n                                            output,\n                                            output,\n                                        ]\n                                    }\n                                } else if ((((((!(self::ml_math::is_integer(position))\n                                    || (position < start))\n                                    || (position >= end))\n                                    || (output != ((output_start + position) - start)))\n                                    || !(self::ml_math::is_integer(width)))\n                                    || (width < 1f64))\n                                    || (width > 4f64))\n                                    || ((position + width) > end)\n                                {\n                                    Vec::<f64>::new()\n                                } else {\n                                    {\n                                        let next = position + width;\n                                        {\n                                            let next_output = output + width;\n                                            vec![\n                                                0f64,\n                                                if next == end { following } else { row },\n                                                if next == end {\n                                                    following_position\n                                                } else {\n                                                    next\n                                                },\n                                                next_output,\n                                                position,\n                                                next,\n                                                output,\n                                                next_output,\n                                            ]\n                                        }\n                                    }\n                                }\n                            }\n                        }\n                    }\n                }\n            }\n        }\n    }\n}",
