    "name": "checkedInventory",
    "inventoryName": "read checked java script tag context inventory",
    "sourceText": "function checkedInventory(program) {\n  return [...program.declarations.values()].map((entry, ordinal) => ({ ordinal, kind: entry.k,\n    name: entry.name, fullName: entry.fullName, modulePath: entry.modulePath }));\n}"
