    "sourceText": "    fn new(tokens: &[Token]) -> Self {\n        Self {\n            kinds: tokens\n                .iter()\n                .map(|token| token_kind(token).to_owned())\n                .collect(),\n            values: tokens.iter().map(|token| token.value.clone()).collect(),\n        }\n    }",
