    "sourceText": "    pub fn number_index(index: f64) -> Option<usize> {\n        if index >= 0.0 && index.fract() == 0.0 && index < 9_007_199_254_740_992.0 {\n            Some(index as usize)\n        } else {\n            None\n        }\n    }",
