    "sourceText": "fn included_range_shorten(tree: &mut SyntaxTree) {\n    let (SyntaxTree::Node { end, .. }\n    | SyntaxTree::Token { end, .. }\n    | SyntaxTree::Error { end, .. }\n    | SyntaxTree::Missing { end, .. }\n    | SyntaxTree::Embed { end, .. }) = tree;\n    *end -= 1;\n}"
