    "sourceText": "fn field_range_sources(\n    host: Grammar,\n    child: Grammar,\n    child_name: &str,\n) -> Vec<GlobalConceptSource> {\n    [(\"Host\", host), (child_name, child)]\n        .into_iter()\n        .map(|(id, grammar)| GlobalConceptSource {\n            id: id.to_owned(),\n            language: id.to_owned(),\n            edition: String::new(),\n            grammar,\n        })\n        .collect()\n}"
