    "sourceText": "fn first_field(tree: &Value) -> Option<&Value> {\n    if tree[\"field\"] == \"value\" && tree[\"trivia\"] != true {\n        return Some(tree);\n    }\n    tree[\"children\"].as_array()?.iter().find_map(first_field)\n}"
